Translate the following GNU C++14 code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++14 code you have to translate:
<original_code>
#include <bits/stdc++.h>

using namespace std;

#define FOR(i,a,b) for(int i=a;i<=b;i++)
#define REV(i,a,b) for(int i=a;i>=b;i--)
#define FORG(i,u) for(int i=head[u];~i;i=e[i].next)

const int N=1e6+5;
const int MOD1=998244353;
const int MOD2=1e9+7;
const int BASE=1000000;

typedef long long ll;
typedef double db;

#define MAX(a,b) ((a)>(b)?(a):(b))
#define MIN(a,b) ((a)<(b)?(a):(b))
#define PAIR pair<int,int>
#define MKP make_pair

template<typename T> void read_input(T &x){
    x=0; int sign=1;
    char c=getchar();
    while(!isdigit(c)){ if(c=='-')sign=-1; c=getchar(); }
    while(isdigit(c)){ x=(x<<1)+(x<<3)+c-'0'; c=getchar(); }
    x*=sign;
}

ll n;
vector<int> v[10];
ll gg;
int sum[10];
int answer;

void dfs1(int u,int x){
    v[u].push_back(((++gg)-x+MOD1)%MOD1);
    sum[u]+=v[u].back()%MOD2;
    sum[u]%=MOD2;
    if(u==6) return;
    FOR(i,0,9) dfs1(u+1,10*x+i);
}

void dfs2(ll x){
    if(x>n) return;
    if(x*BASE+BASE-1<=n && x*BASE*10>n){
        ll rk=gg;
        for(int i=0,bit=1;i<=6;i++,bit*=10){
            int mae=((rk - x*bit)%MOD1+MOD1)%MOD1;
            int pos=lower_bound(v[i].begin(),v[i].end(),-mae+MOD1)-v[i].begin();
            answer+=((1LL*mae*v[i].size()%MOD2+sum[i])%MOD2 - 1LL*(v[i].size()-pos)*MOD1%MOD2 +MOD2)%MOD2;
            answer%=MOD2;
            gg+=v[i].size();
        }
        return;
    }
    answer+=(((++gg)-x)%MOD1+MOD1)%MOD1;
    answer%=MOD2;
    FOR(i,0,9) dfs2(x*10+i);
}

int main()
{
    #ifdef TEST
    freopen("testdata.in","r",stdin);
    freopen("test1.out","w",stdout);
    #endif
    read_input(n);
    dfs1(0,0);
    FOR(i,0,6) sort(v[i].begin(),v[i].end());
    gg=0;
    FOR(i,1,9) dfs2(i);
    printf("%d\n",answer);
    return 0;
}
</original_code>
